current.custom_css:
/* MELATO HOMEPAGE MOBILE REFINEMENT 2026-07-26
   Keeps the announcement compact, cleans the mobile header and concierge,
   differentiates homepage CTAs, and restores card contrast. */

.melato-ann__cta {
  display: none !important;
}

@media screen and (max-width: 989px) {
  .melato-ann {
    display: flex !important;
    min-height: 44px !important;
    height: 44px !important;
    padding: 0 !important;
    gap: 0 !important;
  }

  .melato-ann__badge,
  .melato-ann__cta,
  .melato-ann > span[aria-hidden="true"] {
    display: none !important;
  }

  .melato-ann__viewport {
    width: 100% !important;
    padding-inline: 16px !important;
    mask-image: none !important;
    -webkit-mask-image: none !important;
  }

  .melato-ann__track {
    min-height: 44px !important;
  }

  .melato-ann__group {
    gap: 30px !important;
    padding-right: 30px !important;
  }

  .melato-ann__item {
    font-size: 12px !important;
    line-height: 1 !important;
    letter-spacing: .12em !important;
  }

  .melato-ann__item small {
    display: none !important;
  }

  .mxh .mxh__bar {
    min-height: 64px !important;
    padding: 0 14px !important;
    gap: 8px !important;
  }

  .mxh .mxh__menu {
    width: 40px !important;
    min-width: 40px !important;
    height: 40px !important;
    min-height: 40px !important;
    padding: 0 !important;
    background: transparent !important;
    border-color: rgba(166, 136, 93, .42) !important;
    box-shadow: none !important;
  }

  .mxh .mxh__menu-mark,
  .mxh .mxh__menu-mark svg {
    width: 22px !important;
    height: 22px !important;
  }

  .mxh .mxh__logo-img {
    width: min(var(--mxh-logo-width), 148px) !important;
    max-width: 148px !important;
    max-height: 38px !important;
  }

  .mxh .mxh__bag {
    width: auto !important;
    min-width: 64px !important;
    height: 40px !important;
    min-height: 40px !important;
    padding: 0 8px 0 12px !important;
    gap: 8px !important;
    background: transparent !important;
    border-color: rgba(166, 136, 93, .42) !important;
    box-shadow: none !important;
  }

  .mxh .mxh__bag-count {
    min-width: 20px !important;
    width: 20px !important;
    height: 20px !important;
    background: #a6885d !important;
    color: #080808 !important;
  }

  .concierge-strip--mobile {
    height: 50px !important;
  }

  .concierge-strip__mobile-track {
    display: grid !important;
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
    gap: 8px !important;
    overflow: visible !important;
    padding: 6px 12px !important;
  }

  .concierge-strip__mobile-pill {
    width: 100% !important;
    min-width: 0 !important;
    justify-content: center !important;
    padding: 8px 4px !important;
    border-radius: 10px !important;
    border-color: rgba(244, 234, 216, .18) !important;
  }

  .concierge-strip__mobile-label {
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    font-size: 10px !important;
    letter-spacing: .07em !important;
  }
}

body.template-index .melato-home-conversion__ctas {
  gap: 10px !important;
}

body.template-index .melato-home-conversion__cta,
body.template-index .melato-home-conversion__cta-secondary {
  min-height: 52px !important;
  border-radius: 12px !important;
  letter-spacing: .13em !important;
}

body.template-index .melato-home-conversion__cta {
  background: #a6885d !important;
  color: #080808 !important;
  border: 1px solid #a6885d !important;
  box-shadow: 0 14px 36px rgba(0, 0, 0, .28) !important;
}

body.template-index .melato-home-conversion__cta:hover {
  background: #c2a478 !important;
  border-color: #c2a478 !important;
}

body.template-index .melato-home-conversion__cta-secondary {
  background: #0b0b0b !important;
  color: #f5f1e8 !important;
  border: 1px solid rgba(245, 241, 232, .28) !important;
}

body.template-index .melato-home-conversion__proof-card,
body.template-index .melato-home-conversion__panel {
  background: linear-gradient(145deg, #151515 0%, #0d0d0d 100%) !important;
  border: 1px solid rgba(245, 241, 232, .22) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .035),
              0 18px 44px rgba(0, 0, 0, .24) !important;
}

body.template-index .melato-home-conversion__proof-card strong,
body.template-index .melato-home-conversion__panel h2 {
  color: #fffaf2 !important;
}

body.template-index .melato-home-conversion__proof-card span,
body.template-index .melato-home-conversion__panel p {
  color: rgba(245, 241, 232, .76) !important;
}

@media screen and (max-width: 749px) {
  body.template-index .melato-home-conversion__ctas {
    display: grid !important;
    grid-template-columns: 1fr !important;
  }

  body.template-index .melato-home-conversion__cta,
  body.template-index .melato-home-conversion__cta-secondary {
    width: 100% !important;
  }

  body.template-index .melato-home-conversion__proof {
    gap: 12px !important;
  }

  body.template-index .melato-home-conversion__proof-card,
  body.template-index .melato-home-conversion__panel {
    padding: 24px !important;
  }
}
